for(const id of [14,15])characterMoves[id].forEach((m,n)=>{m.phases=combatKeys[id][n].map((key,i)=>({...m.phases[i],...techniqueBook[key],key,contactFrame:combatContacts[id][n][i],knockdown:i===2,push:i===2?4:0}));m.name=combatNames[id][n];m.signature=m.name;});
function combatFrame(p){
 if(p.hp<=0||p.down>0){const age=Math.max(0,tick-p.hitAt);return p.hp>0&&p.down<12?14:age<8?10:age<16?11:age<24?12:13;}
 if(p.stun>0&&!p.guardStun)return 10;
 if(p.attack!==null){const b=moveFor(p,p.attack),m=attackPhase(b,p.at),row=(p.attack+2)*8;if(p.at<b.start)return row;if(p.at>=b.start+b.active)return row+7;return row+Math.min(7,m.contactFrame+(m.phaseFrame>=7?1:0));}
 if(p.y>0)return 15;if(p.takeoff>0||p.landing>0||p.crouch)return 9;if(p.block)return 8;return Math.floor((((p.ginga%176)+176)%176)/22);
}
function drawPacked(p,im,index,f){if(!im?.complete||!im.naturalWidth)return;ctx.save();ctx.translate(p.x,590-p.y);ctx.scale(p.dir,1);ctx.drawImage(im,index%8*320,Math.floor(index/8)*320,320,320,-160*f,-300*f,320*f,320*f);ctx.restore();}
function drawCompleteFighter(p){drawPacked(p,combatImages[p.id],combatFrame(p),305/combatData[p.id].referenceHeight);}
const flipNames={7:'Jade Inversion',9:'Solar Arc',2:'Memória no Ar',14:'Maré Invertida'};
for(const id of [7,9,2,14]){const old=characterMoves[id][5];characterMoves[id][5]={...old,name:flipNames[id],signature:flipNames[id],start:14,active:42,end:18,phases:['bencao','au','rasteira'].map((key,i)=>({...old.phases[Math.min(i,old.phases.length-1)],...techniqueBook[key],key,frames:14,range:220,damage:9,rank:3,knockdown:i===2,push:i===2?4:0}))};}
function drawVeteranFlip(p){const b=moveFor(p,p.attack),m=attackPhase(b,p.at),index=p.at<b.start?0:p.at>=b.start+b.active?7:1+m.phase*2+(m.phaseFrame>=7?1:0);const d=flipData[p.id],ref=combatData[p.id],rd=redesignData[p.id];const stance=ref?305*ref.stanceHeight/ref.referenceHeight:305*rd.rects[0][3]/rd.referenceHeight;drawPacked(p,flipImages[p.id],index,stance/d.stanceHeight);}
for(const [id,label,detail] of [['watch','CPU VS CPU','CHOOSE TWO FIGHTERS + STAGE'],['watcharcade','WATCH ARCADE','CPU PLAYS THE STORY LADDER']]){const b=document.createElement('button');b.dataset.mode=id;b.innerHTML='<b>'+label+'</b><span>'+detail+' →</span>';b.onclick=()=>setMode(id);document.querySelector('.mode-buttons').append(b);}
function returnToMenu(){arcadeAutoplay=false;stopResultSound();scene='menu';players=[];freeze=0;endWait=0;show('menu');setStageMusic(-1);}
const watchExit=document.createElement('button');watchExit.textContent='RETURN TO MAIN MENU';watchExit.hidden=true;watchExit.onclick=returnToMenu;document.querySelector('.cabinet-top').append(watchExit);
const menuStyle=document.createElement('style');menuStyle.textContent='#menu{overflow-y:auto}.mode-buttons{gap:5px}.mode-buttons button{padding:8px 12px;min-height:44px}#menu .menupanel{padding:12px 24px}.cabinet-top button{font-size:11px}';document.head?.append(menuStyle);
$('#quit').onclick=returnToMenu;
// Intro uses the same correctly scaled fighter sheet as gameplay.
installFighterKits();
if(!document.querySelector('#reviewpanel')){scene='menu';show('menu');}
